wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store (platform-approved grant).
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let notified = notifier::notify(&format!(
            "heartbeat: t={} fetched={} url={}",
            seconds, fetched, feed_url
        ));

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
